/** @param {NS} ns */
export async function main(ns) {
  // Get top-level keys of ns
  const keys = Object.keys(ns);
  ns.tprint('=== NS KEYS ===');
  ns.tprint(keys.join(', '));

  // Try obvious state calls with direct dot notation
  ns.tprint('=== STATE CALLS ===');

  try { ns.tprint('getMoney: ' + ns.getMoney()); } catch(e) { ns.tprint('getMoney err: ' + e); }
  try { ns.tprint('getLevel: ' + ns.getLevel()); } catch(e) { ns.tprint('getLevel err: ' + e); }
  try { ns.tprint('getUpgrades: ' + JSON.stringify(ns.getUpgrades())); } catch(e) { ns.tprint('getUpgrades err: ' + e); }
  try { ns.tprint('getServers: ' + JSON.stringify(ns.getServers())); } catch(e) { ns.tprint('getServers err: ' + e); }
  try { ns.tprint('ls: ' + JSON.stringify(ns.ls('home'))); } catch(e) { ns.tprint('ls err: ' + e); }
  try { ns.tprint('scan: ' + JSON.stringify(ns.scan())); } catch(e) { ns.tprint('scan err: ' + e); }
  try { ns.tprint('help: ' + ns.help('')); } catch(e) { ns.tprint('help err: ' + e); }

  // Print typeof each key
  ns.tprint('=== NS TYPES ===');
  for (const k of keys) {
    try {
      const v = ns[k];
      const t = typeof v;
      if (t === 'object' && v !== null) {
        const subkeys = Object.keys(v);
        ns.tprint(k + ': object {' + subkeys.join(', ') + '}');
      } else {
        ns.tprint(k + ': ' + t);
      }
    } catch(e) {
      ns.tprint(k + ': ERROR ' + e);
    }
  }
}

