/** @param {NS} ns */
export async function main(ns) {
  // Kill existing scripts to free RAM
  ns.killall('home');
  await ns.sleep(500);

  // Nuke n00dles
  try { ns.nuke('n00dles'); } catch(e) {}

  // Write a minimal worker script - only uses ns.hack (1.7GB)
  const worker = `/** @param {NS} ns */
export async function main(ns) {
  while(true) {
    await ns.hack('n00dles');
  }
}
`;

  await ns.write('/worker.js', worker, 'w');
  await ns.sleep(200);

  // Check server money before
  const moneyBefore = ns.getServerMoneyAvailable('n00dles');
  ns.tprint('n00dles money before: $' + moneyBefore);
  ns.tprint('Player money before: $' + ns.getServerMoneyAvailable('home'));

  // Launch worker - it needs 1.7GB RAM
  const pid = ns.run('/worker.js', 1);
  if (pid === 0) {
    ns.tprint('ERROR: Failed to launch worker.js');
  } else {
    ns.tprint('Worker launched with PID: ' + pid);
  }

  // Wait 30 seconds
  await ns.sleep(30000);

  const moneyAfter = ns.getServerMoneyAvailable('n00dles');
  ns.tprint('n00dles money after: $' + moneyAfter);
  ns.tprint('Done waiting.');
}

