/** @param {NS} ns */
export async function main(ns) {
  const used = ns.getServerUsedRam('home');
  const max = ns.getServerMaxRam('home');
  const procs = ns.ps('home');
  ns.tprint('USED=' + used + ' MAX=' + max);
  ns.tprint('PROCS=' + JSON.stringify(procs));
  for (const p of procs) {
    if (p.filename !== '/main.js' && p.filename !== 'main.js') {
      ns.kill(p.pid);
    }
  }
  await ns.sleep(500);
  const used2 = ns.getServerUsedRam('home');
  ns.tprint('USED_AFTER=' + used2);
  const threads = Math.floor((max - used2) / 1.7);
  ns.tprint('THREADS=' + threads);
  await ns.write('/w.js', 'export async function main(ns){while(true){await ns.hack("n00dles");}}', 'w');
  ns.nuke('n00dles');
  if (threads > 0) {
    const pid = ns.run('/w.js', threads);
    ns.tprint('LAUNCHED pid=' + pid + ' threads=' + threads);
  }
}
